const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const TASKS = STATE + '/writer_tasks';
const LOG = '/home/node/.n8n/logs';
// an unguarded mkdirSync throw here would kill the node before the
// Respond node ran: the webhook caller then saw a bare execution
// failure instead of an in-band {ok:false} refusal row - the same
// crash-before-Respond pattern the sibling nodes collect. Flush the
// failures once log() exists below.
// SYNC-BEGIN: mkdir-collect
const mkdirErrs = [];
for (const d of [STATE, TASKS, LOG]) {
  try {
    fs.mkdirSync(d, { recursive: true });
  } catch (e) {
    mkdirErrs.push({ dir: d,
      error: String((e && e.message) || e).slice(0, 150) });
  }
}
// SYNC-END: mkdir-collect
const token = ENV('TELEGRAM_BOT_TOKEN');
// Secrets that can surface inside an httpRequest error string (the
// bot token inside tg() URLs, the dispatch secret header, the pangram
// key in API error text) - String(e) never reaches a reply or log
// verbatim. Same masking discipline as the sibling nodes.
const SECRET_VALUES = [token, ENV('WRITER_DISPATCH_SECRET'),
  ENV('TG_WEBHOOK_SECRET'), ENV('PANGRAM_API_KEY')].filter(Boolean);
// SYNC-BEGIN: scrub-secrets
const scrubSecrets = (s) => {
  let out = String(s);
  for (const v of SECRET_VALUES) {
    if (v && v.length >= 8) out = out.split(v).join('***');
  }
  return out;
};
// SYNC-END: scrub-secrets
const tg = async (method, body) => {
  try {
    // SYNC-BEGIN: tg-timeout
    return await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + token + '/' + method,
      body: body || {},
      json: true,
      // explicit 30s timeout, same as the sibling tg() helpers:
      // helpers.httpRequest is unbounded by default, so a hung
      // api.telegram.org socket would stall the whole dispatch behind it
      timeout: 30000
    });
    // SYNC-END: tg-timeout
  } catch (e) {
    // a send that never landed is otherwise invisible - keep the same
    // compact error trail the sibling tg() keeps
    try {
      log({ action: 'tg-send-failed', endpoint: method,
        class: (e && e.name) || 'Error',
        error: scrubSecrets(String(
          (e && (e.description || e.message)) || e)).slice(0, 200) });
    } catch (e2) {}
    return null;
  }
};
// best-effort by contract: a transient FS failure must NEVER
// propagate out of log() - a thrown append would abort the dispatch
// loop. Same discipline the sibling log() helpers follow.
const log = (rec) => {
  try {
    fs.appendFileSync(LOG + '/writer-dispatch.jsonl',
      JSON.stringify({ ts: new Date().toISOString(), ...rec }) + '\n');
  } catch (e) {}
};
// flush the dir-creation failures collected above
for (const m of mkdirErrs) {
  try { log({ action: 'mkdir-failed', dir: m.dir, error: m.error }); }
  catch (e) {}
}
// same tmp+rename write discipline as the sibling Code nodes.
// SYNC: sibling copies live in Handle TG Update, Prepare Draft,
// Compose Message and Handle Pangram Results (sp-tg-moderation),
// Generate Drafts (sp-content-gen), Resolve Chat + Webhook
// (sp-tg-setup), Analytics Tick (sp-analytics) and Eval Tick
// (sp-humanizer-eval) - replicate any fix to every copy by hand.
// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic
// Cross-execution state serialization (issue #70): parallel webhook
// executions read-modify-write the same task files - withLock
// serializes the RMW on a '<key>.lock' file. fn MUST be synchronous:
// every tg()/httpRequest call stays outside and callers collect
// their follow-up actions into the return value instead.
// SYNC-BEGIN: file-lock
const LOCKS_DIR = STATE + '/locks';
try { fs.mkdirSync(LOCKS_DIR, { recursive: true }); } catch (e) {}
const lockBusyError = () => {
  const e = new Error('state lock busy');
  e.name = 'LockBusyError';
  e.lockBusy = true;
  return e;
};
const withLock = (key, ttlMs, fn) => {
  const lp = LOCKS_DIR + '/' + key + '.lock';
  // no crypto/process in Code nodes - timestamp+random like the
  // writeJsonAtomic tmp names is entropy enough for a lock token
  const mine = Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 10);
  const claim = JSON.stringify({ token: mine, exp: Date.now() + ttlMs });
  let held = false;
  try {
    fs.writeFileSync(lp, claim, { flag: 'wx', mode: 0o600 });
    held = true;
  } catch (e) {
    if (!e || e.code !== 'EEXIST') throw e;
    // only a PROVEN-live lock (readable, exp in the future) makes us
    // busy - anything else is stolen, then verified by re-read
    // because a competing stealer may have won the rename
    let cur = null;
    try { cur = JSON.parse(fs.readFileSync(lp, 'utf8')); } catch (e2) {}
    if (cur && Number.isFinite(Number(cur.exp)) &&
        Date.now() <= Number(cur.exp)) {
      throw lockBusyError();
    }
    const tmp = lp + '.tmp-' + mine;
    try {
      fs.writeFileSync(tmp, claim, { mode: 0o600 });
      fs.renameSync(tmp, lp);
      held = JSON.parse(fs.readFileSync(lp, 'utf8')).token === mine;
    } catch (e3) { held = false; }
    try { fs.unlinkSync(tmp); } catch (e4) {}
    if (!held) throw lockBusyError();
  }
  try {
    return fn();
  } finally {
    if (held) {
      try {
        const cur = JSON.parse(fs.readFileSync(lp, 'utf8'));
        if (cur && cur.token === mine) fs.unlinkSync(lp);
      } catch (e5) {
        // release failures never propagate: a leaked lock expires
        // on its own; ENOENT just means it was already removed
        if (!e5 || e5.code !== 'ENOENT') {
          try {
            if (typeof log === 'function') {
              log({ action: 'lock-release-failed', key: key,
                error: String(e5).slice(0, 120) });
            }
          } catch (e6) {}
        }
      }
    }
  }
};
// SYNC-END: file-lock
// writer-dispatch is reachable through the public edge proxy, so task
// creation needs the same shared-secret gate every other public
// webhook carries (DRAFT_WEBHOOK_SECRET on moderation-draft,
// CONTENT_GEN_WEBHOOK_SECRET on content-gen). Callers must send
// X-Writer-Dispatch-Secret (X-Shared-Token accepted as the compat
// alias the draft gate uses) matching WRITER_DISPATCH_SECRET. Fail
// closed when the env is unset - a dead endpoint beats a public spam
// surface that posts files into a writers' group.
const WEBHOOK_SECRET = ENV('WRITER_DISPATCH_SECRET');
// SYNC-BEGIN: padded-compare
const secretOk = (got) => {
  const a = String(got == null ? '' : got);
  if (!WEBHOOK_SECRET) return false;
  // no early return on a length mismatch: it leaks the expected
  // secret length through response timing on this public endpoint.
  // Pad both operands to a shared length and fold the length delta
  // into diff so a padded tail can never compare equal. The first
  // loop count is a FIXED 64 - a bound of SECRET.length would make
  // the compare cost proportional to the secret's length, the very
  // leak the floor exists to hide, and a.length stays OUT of every
  // bound so an over-long attacker header cannot stretch the compare
  // either. Positions past 64 are NOT ignored: the second loop folds
  // the tail for i < SECRET.length (a per-deployment constant), so a
  // >64 configured secret compares in full instead of degrading to a
  // prefix-only check. padEnd never truncates, and charCodeAt past
  // the end of pa yields NaN (folds as 0 ^ pb char - still a nonzero
  // diff); the length-xor above rejects whatever length mismatch is
  // left.
  const len = 64;
  const pa = a.padEnd(len, '\0');
  const pb = WEBHOOK_SECRET.padEnd(len, '\0');
  let diff = a.length ^ WEBHOOK_SECRET.length;
  for (let i = 0; i < len; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  for (let i = len; i < WEBHOOK_SECRET.length; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  return diff === 0;
};
// SYNC-END: padded-compare

const WRITERS_CHAT = ENV('WRITERS_CHAT_ID');
// UTF-8 bytes via the unescape/encodeURIComponent pair (the same
// trick the inline sha1 in registry-event uses) - no Buffer reliance:
// Code nodes only guarantee require('fs').
const utf8bytes = (s) => unescape(encodeURIComponent(String(s)));
const b64 = (s) => {
  const b = utf8bytes(s);
  const T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz' +
    '0123456789+/';
  let out = '';
  for (let i = 0; i < b.length; i += 3) {
    const c0 = b.charCodeAt(i);
    const c1 = i + 1 < b.length ? b.charCodeAt(i + 1) : null;
    const c2 = i + 2 < b.length ? b.charCodeAt(i + 2) : null;
    out += T.charAt(c0 >> 2) +
      T.charAt(((c0 & 3) << 4) | (c1 === null ? 0 : c1 >> 4)) +
      (c1 === null ? '=' :
        T.charAt(((c1 & 15) << 2) | (c2 === null ? 0 : c2 >> 6))) +
      (c2 === null ? '=' : T.charAt(c2 & 63));
  }
  return out;
};

const out = [];
for (const item of $input.all()) {
  const hdrs = (item.json && item.json.headers) || {};
  const body = (item.json && item.json.body) || {};
  if (!secretOk(hdrs['x-writer-dispatch-secret'] ||
      hdrs['x-shared-token'])) {
    out.push({ json: { kind: 'result', ok: false,
      reason: WEBHOOK_SECRET ? 'unauthorized'
        : 'WRITER_DISPATCH_SECRET not configured - failing closed' } });
    continue;
  }
  const packId = String(body.pack_id || '');
  // pack_id names the task file - a traversal or separator would
  // escape writer_tasks/, so the safe-charset gate runs before any
  // path use
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(packId)) {
    out.push({ json: { kind: 'result', ok: false,
      reason: 'pack_id must match [A-Za-z0-9_-]{1,64}' } });
    continue;
  }
  const brief = String(body.brief_md || '');
  let etalon = String(body.etalon_txt || '');
  const targetWords = Number(body.target_words) || 0;
  const deadlineHours = Number(body.deadline_hours) || 0;
  if (!brief.trim() || !etalon.trim() ||
      !(targetWords > 0) || !(deadlineHours > 0)) {
    out.push({ json: { kind: 'result', ok: false, pack_id: packId,
      reason: 'need brief_md + etalon_txt + target_words>0 + ' +
        'deadline_hours>0' } });
    continue;
  }
  if (!WRITERS_CHAT || !token) {
    out.push({ json: { kind: 'result', ok: false, pack_id: packId,
      reason: 'WRITERS_CHAT_ID or TELEGRAM_BOT_TOKEN not configured' } });
    continue;
  }
  // the etalon ships with the header the package contract pins
  // (writer_interface_spec: "structural reference - paraphrase fails
  // acceptance") - prepend it when the producer did not, so Gate 1's
  // anchoring defence is never undermined by a missing warning
  const ETALON_HEADER =
    'structural reference - paraphrase fails acceptance';
  if (!etalon.startsWith(ETALON_HEADER)) {
    etalon = ETALON_HEADER + '\n\n' + etalon;
  }
  const writerId = body.writer_id != null && body.writer_id !== ''
    ? String(body.writer_id) : null;
  const taskPath = TASKS + '/' + packId + '.json';
  // create-or-resume under the state lock: pack_id is the idempotency
  // key - a retried POST after the card already sent answers
  // 'already' without a duplicate card; a record whose card never
  // landed (crash between write and send, or a failed send) resumes
  // at the send step instead of being wedged forever. card_pending
  // makes a concurrent second dispatch back off while the first is
  // inside the send window (stale after 60s -> resumable).
  let phase = null;
  let task = null;
  let lockErr = null;
  try {
    const r = withLock('writer-task-' + packId, 15000, () => {
      let cur = null;
      try { cur = JSON.parse(fs.readFileSync(taskPath, 'utf8')); }
      catch (e) {}
      const nowIso = new Date().toISOString();
      if (cur && cur.card_message_id) {
        return { phase: 'exists', task: cur };
      }
      const pendingFresh = cur && cur.card_pending &&
        Number.isFinite(Date.parse(cur.card_pending)) &&
        Date.now() - Date.parse(cur.card_pending) < 60000;
      if (pendingFresh) return { phase: 'in-progress', task: cur };
      const t = (cur && typeof cur === 'object') ? cur : {};
      t.pack_id = packId;
      t.status = 'DISPATCHED';
      t.writer_id = writerId || t.writer_id || null;
      t.target_words = targetWords;
      t.deadline_hours = deadlineHours;
      t.attempts = Array.isArray(t.attempts) ? t.attempts : [];
      t.history = Array.isArray(t.history) ? t.history : [];
      t.created_at = t.created_at || nowIso;
      t.updated_at = nowIso;
      t.card_pending = nowIso;
      t.history.push({ ts: nowIso, event: 'dispatch' });
      writeJsonAtomic(taskPath, t);
      return { phase: 'send', task: t };
    });
    phase = r.phase;
    task = r.task;
  } catch (e) {
    lockErr = e;
  }
  if (lockErr) {
    out.push({ json: { kind: 'result', ok: false, pack_id: packId,
      reason: 'state lock failed: ' +
        String((lockErr && lockErr.message) || lockErr).slice(0, 150) } });
    continue;
  }
  if (phase === 'exists') {
    out.push({ json: { kind: 'result', ok: true, pack_id: packId,
      status: task.status, already: true,
      card_message_id: task.card_message_id } });
    continue;
  }
  if (phase === 'in-progress') {
    out.push({ json: { kind: 'result', ok: false, pack_id: packId,
      reason: 'dispatch already in progress' } });
    continue;
  }
  // task card: the single audible sendMessage; the two documents ship
  // captionless through TG Send Doc below
  const caption = 'WRITER TASK ' + packId + ' | ~' + targetWords +
    ' words | deadline ' + deadlineHours + 'h';
  const card = await tg('sendMessage', { chat_id: WRITERS_CHAT,
    text: caption });
  const cardId = card && card.ok && card.result &&
    card.result.message_id;
  // stamp the card outcome under the lock; a failed send is recorded
  // (card_failed_at) so a retry resumes instead of duplicating
  try {
    withLock('writer-task-' + packId, 15000, () => {
      const cur = JSON.parse(fs.readFileSync(taskPath, 'utf8'));
      delete cur.card_pending;
      if (cardId) {
        cur.card_message_id = cardId;
        cur.card_text = caption;
      } else {
        cur.card_failed_at = new Date().toISOString();
      }
      cur.updated_at = new Date().toISOString();
      writeJsonAtomic(taskPath, cur);
      task = cur;
    });
  } catch (e) {
    log({ action: 'dispatch-stamp-failed', pack_id: packId,
      error: String((e && e.message) || e).slice(0, 150) });
  }
  if (!cardId) {
    out.push({ json: { kind: 'result', ok: false, pack_id: packId,
      reason: 'task card send failed - task saved, retry dispatch' } });
    continue;
  }
  log({ action: 'dispatched', pack_id: packId, card_message_id: cardId,
    target_words: targetWords, deadline_hours: deadlineHours,
    writer_id: writerId });
  // one sendDocument item per file: TG Send Doc ships every input
  // item's binary.file as `document`; Finalize Dispatch pairs the
  // results positionally back to these rows
  out.push({ json: { kind: 'doc', pack_id: packId, doc: 'brief',
    chat_id: WRITERS_CHAT },
    binary: { file: { data: b64(brief), mimeType: 'text/markdown',
      fileName: 'brief_pack.md' } } });
  out.push({ json: { kind: 'doc', pack_id: packId, doc: 'etalon',
    chat_id: WRITERS_CHAT },
    binary: { file: { data: b64(etalon), mimeType: 'text/plain',
      fileName: 'etalon.txt' } } });
}
return out;

