    const res = docResults[i] && docResults[i].json;
    const mid = res && res.ok && res.result && res.result.message_id;
    const errTxt = res && res.error
      ? (res.error.message || res.error.description || res.error)
      : (res && res.description) || res;
    // the httpRequest error text can embed the bot-token URL -
    // scrub before it lands in the task record, same discipline as
    // the sibling tg() error trails
    del[d.json.doc] = { ok: !!mid, message_id: mid || null,
      error: mid ? null :
