// Pangram REST scan helpers - adapted from Prepare Draft's api-mode
// path (sp-tg-moderation, issue #125): same request contract (POST
// /task, bounded GET /task/{id} polling), same retry semantics
// (transient backoff with jitter, Retry-After slept verbatim and
// capped, 4xx fails fast) and the same error_class vocabulary. The
// helpers are NOT inside a SYNC group - Prepare Draft is currently
// the only other copy; keep them aligned by hand.
const pangramSleep = (ms) => new Promise((r) => setTimeout(r, ms));
const pangramHttpStatus = (e) => {
  const s = Number(e && (e.statusCode || e.status ||
    (e.response && (e.response.statusCode || e.response.status))));
