// so a hostile/buggy value cannot park the poll.
const PANGRAM_RETRY_AFTER_CAP_MS = 30000;
const pangramRetryAfterMs = (e) => {
  const h = e && e.response && e.response.headers;
  const raw = h && (h['retry-after'] || h['Retry-After']);
  if (raw === undefined || raw === null) return null;
  const secs = Number(raw);
  if (Number.isFinite(secs) && secs >= 0) return secs * 1000;
  const t = Date.parse(String(raw));
  if (Number.isFinite(t)) return Math.max(0, t - Date.now());
  return null;
};
const pangramApiReq = async (opts) => {
  let lastErr = null;
  for (let attempt = 1; attempt <= PANGRAM_API_MAX_ATTEMPTS; attempt++) {
    try {
      return await this.helpers.httpRequest({
        method: opts.method,
        url: PANGRAM_API_BASE + opts.path,
        headers: { 'x-api-key': PANGRAM_API_KEY },
        body: opts.body,
        json: true,
        timeout: PANGRAM_API_TIMEOUT_MS
      });
    } catch (e) {
      lastErr = e;
      const s = pangramHttpStatus(e);
      // 4xx fails fast: auth and request-shape faults are terminal
      if (s && s >= 400 && s < 500 && s !== 429) throw e;
      if (attempt < PANGRAM_API_MAX_ATTEMPTS) {
        // Retry-After sleeps verbatim (still capped); jitter applies
        // ONLY to the computed exponential backoff
        const ra = pangramRetryAfterMs(e);
