};
const pangramApiCheck = async (text) => {
  const w = pangramWords(text);
  if (!PANGRAM_API_KEY) {
    return { ok: false, error_class: 'config',
      error: 'PANGRAM_API_KEY not configured', words: w };
  }
  const errOut = (e, extra) => {
    const s = pangramHttpStatus(e);
    return { ok: false,
      error_class: s ? 'http_' + s : 'transient_exhausted',
      error: scrubSecrets(String((e && (e.description || e.message)) || e))
        .slice(0, 150),
      words: w, ...(extra || {}) };
  };
  let created = null;
  try {
    const r = await pangramApiReq({ method: 'POST', path: '/task',
      body: { text: String(text), model: PANGRAM_API_MODEL } });
    created = r && r.task_id ? r
      : (r && r.body && r.body.task_id ? r.body : null);
  } catch (e) {
    return errOut(e);
  }
  if (!created || !created.task_id) {
    return { ok: false, error_class: 'protocol',
      error: 'no task_id in POST /task response', words: w };
  }
  const taskId = created.task_id;
  const deadline = Date.now() + PANGRAM_API_TASK_BUDGET_MS;
  for (;;) {
    // the budget is checked BEFORE each poll, not only between
    // bursts: a slow request retry chain inside pangramApiReq can
    // overshoot the deadline
    if (Date.now() > deadline) {
      return { ok: false, error_class: 'timeout',
        error: 'task polling budget exceeded',
        task_id: taskId, words: w };
    }
    let body = null;
    try {
      const r = await pangramApiReq({ method: 'GET',
        path: '/task/' + encodeURIComponent(taskId) });
      body = r && typeof r === 'object' && r.body &&
        typeof r.body === 'object' ? r.body : r;
    } catch (e) {
      return errOut(e, { task_id: taskId });
    }
    if (body && body.stage === 'STAGE_SUCCESS') {
      const score = Number(body.fraction_ai);
      return { ok: true,
        label: String(body.headline || body.prediction_short || ''),
        short: String(body.prediction_short || ''),
        score: Number.isFinite(score) ? score : null,
        version: body.version || null,
        task_id: taskId, words: w };
    }
    if (body && body.stage === 'STAGE_FAILED') {
      return { ok: false, error_class: 'task_failed',
        error: String(body.headline || 'task failed').slice(0, 150),
        task_id: taskId, words: w };
    }
    if (Date.now() > deadline) {
      return { ok: false, error_class: 'timeout',
        error: 'task polling budget exceeded',
        task_id: taskId, words: w };
    }
    await pangramSleep(PANGRAM_API_POLL_MS);
  }
};

