// writer sent, not a re-rendered copy - the owner moderates exactly
// what was scanned
const forwardDraft = async (task) => {
  if (!ownerChat || !token) return false;
  const at = Array.isArray(task.attempts) ? task.attempts : [];
  const last = at[at.length - 1];
  if (!last || !last.message_id || !WRITERS_CHAT) return false;
  const r = await tg('forwardMessage', { chat_id: ownerChat,
    from_chat_id: WRITERS_CHAT, message_id: last.message_id });
  return !!(r && r.ok);
};
const tellOwner = async (text) => {
  if (!ownerChat || !token) return false;
  const r = await tg('sendMessage', { chat_id: ownerChat,
    text: cap(text, 900) });
  return !!(r && r.ok);
};

const summary = { scanned: 0, applied: 0, stale: 0, timeouts: 0,
  stale_locks: 0, errors: 0 };
const files = listDir(ORIG_DONE) || [];
for (const f of files) {
  const m = /^(.+)_v(\d+)\.json$/.exec(f);
  if (!m) continue;
  const packId = m[1];
  const v = Number(m[2]);
  const fp = ORIG_DONE + '/' + f;
  let verdict = null;
  try { verdict = JSON.parse(fs.readFileSync(fp, 'utf8')); }
  catch (e) {
    // a torn verdict cannot be trusted - consume it and escalate the
    // task below rather than re-reading it every poll
    verdict = { error: 'unreadable verdict file' };
  }
  summary.scanned++;
  const task = loadTask(packId);
  const pending = task && task.orig_pending;
  if (!task || task.status !== 'WAIT_ORIGINALITY' ||
      !pending || pending.v !== v) {
    // verdict for a moved-on task: consume so it cannot pile up, log
    // for the audit trail
    consume(fp);
    summary.stale++;
    log({ action: 'originality-stale', pack_id: packId, v: v });
    continue;
  }
  const percent = verdict && verdict.percent != null
    ? Number(verdict.percent) : null;
  const band = (verdict && verdict.error) || !Number.isFinite(percent)
    ? 'error'
    : (percent <= ORIG_GREEN ? 'green'
      : (percent <= ORIG_YELLOW ? 'yellow' : 'red'));
  const attempts = Array.isArray(task.attempts) ? task.attempts : [];
  const nextStatus = band === 'green' || band === 'yellow'
    ? 'ACCEPTED_TO_MODERATION'
    : band === 'red'
      ? (attempts.length >= MAX_ATTEMPTS ? 'ESCALATED_MAX_RETRIES'
        : 'REJECTED_RETRY_AVAILABLE')
      : 'ESCALATED_GATE_ERROR';
  const borderline = band === 'yellow';
  // stamp verdict + status under the task lock; the entry check above
  // ran on an unlocked read, so the 'already moved on' verdict must be
  // re-verified INSIDE the lock - a raced poll that applied this
  // verdict first returns false here and the file is consumed as
  // stale below, never re-notifying owner/writer a second time
  let stamped = false;
  try {
    stamped = !!withLock('writer-task-' + packId, 15000, () => {
      const cur = JSON.parse(fs.readFileSync(
        TASKS + '/' + packId + '.json', 'utf8'));
      if (cur.status !== 'WAIT_ORIGINALITY' || !cur.orig_pending ||
          cur.orig_pending.v !== v) return false;
      const at = Array.isArray(cur.attempts) ? cur.attempts : [];
      const rec = at.find((a) => a && a.v === v);
      if (rec) {
        rec.originality = { ...(rec.originality || {}),
          percent: percent, band: band,
          error: verdict && verdict.error || null,
          at: new Date().toISOString() };
      }
      cur.attempts = at;
      cur.status = nextStatus;
      delete cur.orig_pending;
      if (borderline) cur.borderline = true;
      cur.updated_at = new Date().toISOString();
      cur.history = Array.isArray(cur.history) ? cur.history : [];
      cur.history.push({ ts: cur.updated_at,
        event: 'originality', v: v, percent: percent, band: band,
        status: nextStatus });
      writeJsonAtomic(TASKS + '/' + packId + '.json', cur);
      task.status = nextStatus;
      task.attempts = cur.attempts;
      return true;
    });
  } catch (e) {
    summary.errors++;
    log({ action: 'originality-stamp-failed', pack_id: packId,
      error: String((e && e.message) || e).slice(0, 150) });
    continue;
  }
  if (!stamped) {
    // lost the race: the owning task already consumed this verdict (or
    // moved past WAIT_ORIGINALITY) - consume the file so it cannot
    // pile up, but skip every notification
    consume(fp);
    summary.stale++;
    log({ action: 'originality-stale', pack_id: packId, v: v });
    continue;
  }
  summary.applied++;
  consume(fp);
  log({ action: 'originality-verdict', pack_id: packId, v: v,
    percent: percent, band: band, status: nextStatus });
  // notify owner + writer AFTER the durable stamp - a failed send
  // retries implicitly on the next failed-attempt path, never blocks
  // the state transition
  const pg = attempts.find((a) => a && a.v === v);
  const pgScore = pg && pg.pangram && pg.pangram.score != null
    ? Number(pg.pangram.score).toFixed(2) : '-';
  if (nextStatus === 'ACCEPTED_TO_MODERATION') {
    await forwardDraft(task);
    await tellOwner('WRITER TASK ' + packId +
      ': ACCEPTED_TO_MODERATION (v' + v + ')' +
      (borderline ? ' [borderline AI score - check the style]' : '') +
      '\n' + scoreHistory(task));
    await tellWriter(task, 'draft v' + v + ' accepted' +
      (borderline ? ' (borderline score - under editor review)' : '') +
      ' and passed to moderation.');
  } else if (nextStatus === 'ESCALATED_GATE_ERROR') {
    await forwardDraft(task);
    await tellOwner('WRITER TASK ' + packId +
      ': ESCALATED_GATE_ERROR - Originality unavailable' +
      (verdict && verdict.error
        ? ' (' + cap(verdict.error, 120) + ')' : '') +
      ', Pangram: ' + pgScore + '. Draft forwarded above.');
    await tellWriter(task,
      'the originality scanner failed - the editor was notified ' +
        'and your draft is safe.');
  } else {
    // red band: retry while attempts remain, escalate when spent
    if (nextStatus === 'ESCALATED_MAX_RETRIES') {
      await forwardDraft(task);
      await tellOwner('WRITER TASK ' + packId +
        ': ESCALATED_MAX_RETRIES (originality ' + percent +
        '% > ' + ORIG_YELLOW + ').\n' + scoreHistory(task));
      await tellWriter(task, 'draft v' + v + ' scored ' + percent +
        '% originality - no retries left, the task is with the ' +
        'editor.');
    } else {
      await tellWriter(task, 'draft v' + v + ' scored ' + percent +
        '% originality (> ' + ORIG_YELLOW + '%) - rewrite and ' +
        'resubmit (attempt ' + v + '/' + MAX_ATTEMPTS + ').');
    }
  }
}
// worker-timeout sweep: a queued scan with no verdict inside
// ORIG_TIMEOUT_MS is escalated Pangram-only (spec: writer's work is
// never lost to infrastructure failure). The queue file stays - a
// late worker result is consumed as stale by the loop above.
for (const f of (listDir(TASKS) || [])) {
  if (!/\.json$/.test(f) || f.indexOf('.tmp-') !== -1) continue;
  let task = null;
  try { task = JSON.parse(fs.readFileSync(TASKS + '/' + f, 'utf8')); }
  catch (e) { continue; }
  if (!task || task.status !== 'WAIT_ORIGINALITY' ||
      !task.orig_pending) continue;
  const at = Date.parse(task.orig_pending.at);
  if (!Number.isFinite(at) || Date.now() - at < ORIG_TIMEOUT_MS) {
    continue;
  }
  const packId = task.pack_id;
  const v = task.orig_pending.v;
  try {
    withLock('writer-task-' + packId, 15000, () => {
      const cur = JSON.parse(fs.readFileSync(
        TASKS + '/' + packId + '.json', 'utf8'));
      if (cur.status !== 'WAIT_ORIGINALITY') return;
      cur.status = 'ESCALATED_GATE_ERROR';
      delete cur.orig_pending;
      cur.updated_at = new Date().toISOString();
      cur.history = Array.isArray(cur.history) ? cur.history : [];
      cur.history.push({ ts: cur.updated_at,
        event: 'originality-timeout', v: v });
      writeJsonAtomic(TASKS + '/' + packId + '.json', cur);
      task.status = cur.status;
    });
    summary.timeouts++;
  } catch (e) {
    summary.errors++;
    log({ action: 'originality-timeout-stamp-failed',
      pack_id: packId,
      error: String((e && e.message) || e).slice(0, 150) });
    continue;
  }
  log({ action: 'originality-timeout', pack_id: packId, v: v });
  const attempts = Array.isArray(task.attempts) ? task.attempts : [];
  const pg = attempts.find((a) => a && a.v === v);
  const pgScore = pg && pg.pangram && pg.pangram.score != null
    ? Number(pg.pangram.score).toFixed(2) : '-';
  await forwardDraft(task);
  await tellOwner('WRITER TASK ' + packId +
    ': ESCALATED_GATE_ERROR - Originality timed out after ' +
    Math.round(ORIG_TIMEOUT_MS / 60000) + 'min, Pangram: ' +
    pgScore + '. Draft forwarded above.');
  await tellWriter(task,
    'the originality scan timed out - the editor was notified ' +
      'and your draft is safe.');
}
// stale-lock sweep: LOCKED_SCANNING past LOCK_TIMEOUT_MS means the
// intake stamp landed but no gate write ever followed (the submission
// intake is the only LOCKED_SCANNING producer, every gate moves the
// task forward). Attempts remaining -> REJECTED_RETRY_AVAILABLE so the
// writer resubmits; spent -> ESCALATED_GATE_ERROR forwarded to the
// owner. The draft survives either way in attempts[]/submissions/ -
// 'never lose a draft' is the spec invariant.
for (const f of (listDir(TASKS) || [])) {
  if (!/\.json$/.test(f) || f.indexOf('.tmp-') !== -1) continue;
  let task = null;
  try { task = JSON.parse(fs.readFileSync(TASKS + '/' + f, 'utf8')); }
  catch (e) { continue; }
  if (!task || task.status !== 'LOCKED_SCANNING') continue;
  // updated_at is the last state write - nothing refreshes it while a
  // task sits wedged, so its age measures the stall
  const lockedAt = Date.parse(task.updated_at);
  if (!Number.isFinite(lockedAt) ||
      Date.now() - lockedAt < LOCK_TIMEOUT_MS) continue;
  const packId = task.pack_id;
  const lat = Array.isArray(task.attempts) ? task.attempts : [];
  const nextStatus = lat.length < MAX_ATTEMPTS
    ? 'REJECTED_RETRY_AVAILABLE' : 'ESCALATED_GATE_ERROR';
  let released = false;
  try {
    released = !!withLock('writer-task-' + packId, 15000, () => {
      const cur = JSON.parse(fs.readFileSync(
        TASKS + '/' + packId + '.json', 'utf8'));
      if (cur.status !== 'LOCKED_SCANNING') return false;
      // the wedged attempt's dedup hash must go: the file was never
      // actually scanned, so an identical resend hitting the intake
      // 'dup' wall would re-wedge a task we just released. The record
      // itself (path, message_id, sha in history) stays - draft kept
      const cat = Array.isArray(cur.attempts) ? cur.attempts : [];
      const wedged = cat[cat.length - 1];
      if (wedged && wedged.sha256) {
        wedged.scan = 'interrupted';
        delete wedged.sha256;
        cur.attempts = cat;
      }
      cur.status = nextStatus;
      cur.updated_at = new Date().toISOString();
      cur.history = Array.isArray(cur.history) ? cur.history : [];
      cur.history.push({ ts: cur.updated_at,
        event: 'scan-lock-timeout', status: nextStatus });
      writeJsonAtomic(TASKS + '/' + packId + '.json', cur);
      task.status = cur.status;
      return true;
    });
  } catch (e) {
    summary.errors++;
    log({ action: 'scan-lock-release-failed', pack_id: packId,
      error: String((e && e.message) || e).slice(0, 150) });
    continue;
  }
  if (!released) continue;
  summary.stale_locks++;
  log({ action: 'scan-lock-timeout', pack_id: packId,
    status: nextStatus });
  if (nextStatus === 'ESCALATED_GATE_ERROR') {
    await forwardDraft(task);
    await tellOwner('WRITER TASK ' + packId +
      ': ESCALATED_GATE_ERROR - the draft scan wedged past ' +
      Math.round(LOCK_TIMEOUT_MS / 60000) +
      'min and no retries remain. Draft forwarded above.');
    await tellWriter(task,
      'the scan of your last draft got stuck and no retries remain ' +
        '- the editor was notified and your draft is safe.');
  } else {
    await tellWriter(task,
      'the scan of your last draft was interrupted - please resend ' +
        'the file as a reply to the task card.');
  }
}
return [{ json: { ok: true, ...summary } }];
